public class Melissa
{

	public static void main(String args[]) throws FileNotFoundException
	{
        Scanner s;
		if(args.length==0)
            s = new Scanner(new File("melissa.dat"));
        else
            s = new Scanner(new File(args[0]));

        int numCases=s.nextInt();
        s.nextLine();
        for(int i=0;i<numCases;i++)
        {
        	int number=s.nextInt();
        	int numberCopy=number;
        	int product=number;
        	while(number>9)
        	{
        		product=1;
        		while(number>0)
        		{
        			int digit=number%10;
        			number/=10;
        			if(digit==0)
        				continue;
        			product*=digit;
        		}
        		number=product;
        	}
        	System.out.println(numberCopy+" -> " + product);
        }
        s.close();
    }
}

import java.util.*;
import java.io.*;
import static java.lang.System.out;
public class Pablo {

	public static void main(String[] args) throws IOException{
		Scanner file = new Scanner(new File("pablo.dat"));
		final int R = 6371;
		int n = file.nextInt();
		for(int x = 1; x <= n; x++) {
			double lat1 = file.nextDouble();
			double lon1 = file.nextDouble();
			double lat2 = file.nextDouble();
			double lon2 = file.nextDouble();
			double latDiff = Math.toRadians(lat2-lat1);
			double lonDiff = Math.toRadians(lon2-lon1);
			double a = Math.sin(latDiff / 2) * Math.sin(latDiff / 2) + Math.cos(Math.toRadians(lat1)) * Math.cos(Math.toRadians(lat2)) * Math.sin(lonDiff / 2) * Math.sin(lonDiff / 2);
			double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
			double distance = R * c;
			out.printf("The distance between (%1.5f, %1.5f) and (%1.5f, %1.5f) is %1d meters.\n",lat1,lon1,lat2,lon2,Math.round(distance * 1000));
		}

	}

}

import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Reka {
    public static void main(String[] args) throws IOException {
        Scanner scan = new Scanner(new File("reka.dat"));
        int T = scan.nextInt();
        assert 1 <= T && T <= 50;

        for (int caseNum = 1; caseNum <= T; caseNum++) {
            System.out.printf("Case #%d: %s\n", caseNum, solve(scan));
        }
    }

    private static String solve(Scanner scan) {
        long L = scan.nextLong();
        int c = scan.nextInt();

        assert 1 <= L && L <= 1e18;
        assert 0 <= c && c <= 200;
        assert c <= L;

        long pairs = (L + 1) / 2;

        Map<Long, Character> map = new HashMap<>();
        for (int i = 0; i < c; i++) {
            long idx = scan.nextLong();
            String s = scan.next();
            assert Pattern.matches("^[a-z]$", s);

            map.put(idx, s.charAt(0));
            pairs--;
        }

        for (Map.Entry<Long, Character> entry : map.entrySet()) {
            long other = L + 1 - entry.getKey();
            if (other == entry.getKey()) {
                // In the middle, nothing to do
            } else if (entry.getKey() < other && map.containsKey(other)) {
                // We have a matching pair of indices. Ensure the characters are equal. If not, no solution.
                if (entry.getValue() != map.get(other)) {
                    return "0";
                }

                // We overcounted the number of pairs
                pairs++;
            }
        }

        long exp = pairs;

        final long MOD = 1_000_000_000;

        // answer is 26^pairs
        long ans = 1;
        long base = 26L;
        while (exp > 0) {
            if (exp % 2 == 1) {
                ans = ans * base % MOD;
            }

            base = base * base % MOD;
            exp /= 2;
        }

        if (pairs >= 7) {
            // This is the tricky part of this problem: need leading
            // 0s, but only if the answer is >= 10^9
            return String.format("%09d", ans);
        } else {
            return Long.toString(ans);
        }
    }
}

import java.util.*;
import java.io.*;
import static java.lang.System.out;
public class Timothy {
	
	public static ArrayList<Number> list = new ArrayList<Number>();

	public static void main(String[] args) throws IOException{
		Scanner file = new Scanner(new File("timothy.dat"));
		while(file.hasNextInt()) {
			int currentNumber = file.nextInt();
			int position = find(currentNumber);
			if(position != -1)
				list.get(position).incrementCount();
			else
				list.add(new Number(currentNumber));
			}
		Collections.sort(list);
		for(Number n:list)
			out.println(n);
		}

	
	
	public static int find(int n) {
		for(int x = 0; x < list.size(); x++) 
			if(n == list.get(x).number)
				return x;
		return -1;
	}
	
	public static class Number implements Comparable{
		int number;
		int count;
		
		public Number(int n) {
			number = n;
			count = 1;
		}
		
		public void incrementCount() {
			count++;
		}
		
		public String toString() {
			if(count > 1)
				return number + " " + (count - 1);
			else
				return "" + number;
		}

		public int compareTo(Object num) {
			Number n = (Number)num;
			if(n.number < number)
				return -1;
			else if(n.number > number)
				return 1;
			else
				return 0;
		}
	}

}
